<?php require_once __DIR__.'/business-grid.php';require_once __DIR__.'/business-production.php';$plan=isset($_GET['id'])?query('SELECT * FROM biz_production_plans WHERE id=?',[(int)$_GET['id']])->fetch():null;if(isset($_GET['id'])&&!$plan)throw new InvalidArgumentException('생산 계획을 찾을 수 없습니다.');$day=$plan['plan_date']??validDate($_GET['plan_date']??$_GET['day']??date('Y-m-d'));$title=$plan['title']??textfield($_GET,'title',100)?:'생산 계획';$selected=is_array($_GET['batches']??null)?$_GET['batches']:[];$snapshot=$plan?json_decode($plan['snapshot'],true):['orders'=>[]];$quantities=[];
